package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where
 * {@code REGION} is the owner's region derived from the postcode (falling back to the
 * city-to-region table, or {@code UNKNOWN} when neither resolves — see {@link OwnerLocality})
 * and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
 * {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}).
 *
 * <p>The identity is deterministic from the owner's own fields alone — there is no per-city
 * sequence number any more, so it no longer depends on how many owners already exist. The
 * telephone is taken in its canonical E.164 form ({@link OwnerTelephone#toE164(String)}, the same
 * normalisation {@link NormalizeOwnerTelephone} already applied upstream) so the hash is stable
 * regardless of how the number was originally formatted.
 *
 * <p>This {@code customerCode} is the single region-and-hash identity every derived owner value
 * flows from: the {@code membershipNumber} and its {@code checkDigit}, the create audit record and
 * the read-time {@code locality} all read it rather than recomputing region independently.
 *
 * <p>Runs after {@link BuildOwner} (which maps the normalised request onto the owner) and before
 * {@link AssignMembershipNumber} and {@link SaveOwner}.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner) {
        String region = OwnerLocality.regionFor(owner.getPostcode(), owner.getCity());
        String regionCode = region != null ? region : "UNKNOWN";
        owner.setCustomerCode(regionCode + "-" + hash8(normalizedTelephone(owner.getTelephone()) + owner.getLastName()));
    }

    /** The owner's telephone in canonical E.164 form, or its raw value when it cannot form one. */
    private static String normalizedTelephone(String telephone) {
        String e164 = OwnerTelephone.toE164(telephone);
        return e164 != null ? e164 : (telephone == null ? "" : telephone);
    }

    /** The first 8 upper-case hex characters (4 bytes) of SHA-256 over {@code value}. */
    private static String hash8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}

